<?php
declare(strict_types=1);
$action=$argv[1]??'report';$e=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $l){$l=trim($l);if($l===''||$l[0]==='#'||!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$e[trim($k)]=trim(trim($v),'"\'');}
$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];$u=new PDO('mysql:host='.$e['GPT_DB_HOST'].';port='.$e['GPT_DB_PORT'].';dbname=guniversal_dbp;charset=utf8mb4',$e['GPT_DB_USERNAME'],$e['GPT_DB_PASSWORD'],$opts);$db=[];foreach(['gmodelo_dbp','gmodelo2_dbp'] as $name)$db[$name]=new PDO('mysql:host='.$e['GPT_DB_HOST'].';port='.$e['GPT_DB_PORT'].';dbname='.$name.';charset=utf8mb4',$e['GPT_DB_USERNAME'],$e['GPT_DB_PASSWORD'],$opts);
$marker='ISOLAMENTO_MODELO2_20260922';
if($action==='start'){$u->exec("UPDATE empresa SET status='ATIVA' WHERE codigo='MODELO2' AND banco_dados='gmodelo2_dbp'");foreach($db as $pdo){$s=$pdo->prepare('INSERT INTO li_condicionantes (CODLICENCA,DSCCONDICIONANTE,FREQUENCIA,ATENDIDO,OBS) VALUES (1,:d,\'Mensal\',\'NAO\',\'Registro controlado de isolamento\')');$s->execute(['d'=>$marker]);}echo json_encode(['action'=>'start','marker'=>$marker,'status'=>'ATIVA']).PHP_EOL;exit;}
if($action==='finish'){$removed=[];foreach($db as $name=>$pdo){$s=$pdo->prepare('DELETE FROM li_condicionantes WHERE DSCCONDICIONANTE=:d');$s->execute(['d'=>$marker]);$removed[$name]=$s->rowCount();}$u->exec("UPDATE empresa SET status='INATIVA' WHERE codigo='MODELO2' AND banco_dados='gmodelo2_dbp'");echo json_encode(['action'=>'finish','removed'=>$removed,'status'=>'INATIVA']).PHP_EOL;exit;}
$out=[];foreach($db as $name=>$pdo){$out[$name]=['marker'=>(int)$pdo->query("SELECT COUNT(*) FROM li_condicionantes WHERE DSCCONDICIONANTE='".$marker."'")->fetchColumn(),'requisitos'=>(int)$pdo->query('SELECT COUNT(*) FROM vw_modulolegal_requisitos_grid')->fetchColumn(),'licencas'=>(int)$pdo->query('SELECT COUNT(*) FROM vw_licencas_grid')->fetchColumn(),'condicionantes'=>(int)$pdo->query('SELECT COUNT(*) FROM vw_licencas_condicionantes_grid')->fetchColumn(),'unidades'=>(int)$pdo->query('SELECT COUNT(*) FROM unidades')->fetchColumn(),'usuarios'=>(int)$pdo->query('SELECT COUNT(*) FROM usuarios')->fetchColumn()];}$out['empresa']=$u->query("SELECT nome,banco_dados,status FROM empresa WHERE codigo='MODELO2'")->fetch();echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
